return $input.all().map((i) => i.json).filter((r) => r.text).map((r) => ({ json: {
  message: `⭐ ${r.rating}/5 on ${r.appName} (${[r.country?.toUpperCase(), r.appVersion && `v${r.appVersion}`].filter(Boolean).join(', ')}): *${r.title || ''}*\n${(r.text || '').slice(0, 600)}\n${r.reviewUrl || ''}`,
} }));
